#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=7

banner "mealdeal archive storage"

# ── 1. Preflight ──────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the things this wizard needs before you touch a browser."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  printf '  %s✓%s gh is installed and authenticated\n' "$GREEN" "$RESET"
else
  warn "gh is missing or not logged in. Run 'gh auth login' in another"
  note "  terminal first, otherwise the secrets will have to be set by hand."
fi

REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo "")
if [[ -n "$REPO" ]]; then
  printf '  %s✓%s secrets will be set on %s\n' "$GREEN" "$RESET" "$REPO"
else
  warn "couldn't identify the GitHub repo from here; are you inside the clone?"
fi

if [[ -f .github/workflows/archive.yml ]]; then
  printf '  %s✓%s .github/workflows/archive.yml is present\n' "$GREEN" "$RESET"
else
  warn "no .github/workflows/archive.yml here, so there is nothing to feed."
fi
note ""
note "A scheduled workflow only runs from the repository's default branch, and"
note "it can only be triggered by hand once it is there. If the workflow is"
note "still on a feature branch, merge it to main before the last stage."
pause "Press Enter when you're ready to start on Cloudflare."

# ── 2. Cloudflare account ─────────────────────────────────────────────────
stage "Cloudflare: sign in"
say "R2 is Cloudflare's object storage. It is S3-compatible, which is why the"
say "workflow can talk to it with the ordinary AWS CLI."
open_url "https://dash.cloudflare.com/"
step "Sign in, or create an account if you don't have one (it's free)."
note ""
note "At this archive's size — roughly 40 KB per chain per day compressed —"
note "a year of both chains is a few tens of megabytes, comfortably inside"
note "R2's free tier. Cloudflare may still ask you to put a card on file when"
note "you first enable R2; that is their policy, not a charge for this usage."
pause "Signed in?"

# ── 3. Create the bucket ──────────────────────────────────────────────────
stage "R2: create the bucket"
say "This is where each day's archived responses will land."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "If R2 isn't enabled yet, follow the prompt to enable it."
step "Click 'Create bucket'."
step "Name it: mealdeal-archive"
step "For location, choose the EU (the data is Dutch, and keeping it in the"
step "  EU avoids a question you'd otherwise have to answer later)."
step "Leave the rest at their defaults and create it."
note ""
note "The bucket must stay private. Nothing in this archive should be public:"
note "it is bulk copies of other companies' price data."
ask R2_BUCKET "Bucket name [mealdeal-archive]:"
[[ -z "$R2_BUCKET" ]] && R2_BUCKET="mealdeal-archive"
write_env R2_BUCKET "$R2_BUCKET"

# ── 4. Account ID ─────────────────────────────────────────────────────────
stage "R2: account ID"
say "The workflow builds the R2 endpoint hostname out of your account ID."
step "Still on the R2 page, find 'Account ID' in the details panel on the right."
step "If you can't spot it, read it out of the browser's address bar instead:"
step "  dash.cloudflare.com/<THIS-IS-THE-ACCOUNT-ID>/r2/overview"
note ""
note "It looks like 32 characters of hex, e.g. 8f14e45fceea167a5a36dedd4bea2543"
ask R2_ACCOUNT_ID "Paste the account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"

# ── 5. API token ──────────────────────────────────────────────────────────
stage "R2: API token"
say "A token scoped to R2 only, so a leak can't touch the rest of the account."
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "Click 'Create API token' (it may read 'Manage API tokens' first)."
step "Permission: 'Object Read & Write' — NOT Admin. The workflow only ever"
step "  reads and writes objects; it never needs to create or delete buckets."
step "Scope it to the single bucket you just created, if offered the choice."
step "Create the token."
note ""
warn "The secret is shown exactly once. Copy both values before leaving the page."
note ""
ask_secret R2_ACCESS_KEY_ID "Paste the Access Key ID:"
ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
note ""
note "All four values are now in .env, which is gitignored. The workflow does"
note "not read .env — it reads the GitHub secrets set in the next stage — but"
note "having them locally lets you run 'aws s3 sync' against the bucket by hand."

# ── 6. GitHub secrets ─────────────────────────────────────────────────────
stage "GitHub: repository secrets"
say "Handing the same four values to Actions, which is what the daily job uses."
set_secret R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
set_secret R2_BUCKET "$R2_BUCKET"
set_secret R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
set_secret R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
printf '\n'
say "Verifying they actually landed:"
MISSING=""
for name in R2_ACCOUNT_ID R2_BUCKET R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY; do
  if gh secret list --json name --jq '.[].name' 2>/dev/null | grep -qx "$name"; then
    printf '  %s✓%s %s is set on the repo\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗%s %s is NOT set\n' "$RED" "$RESET" "$name"
    MISSING="$MISSING $name"
  fi
done
if [[ -n "$MISSING" ]]; then
  printf '\n'
  warn "missing:$MISSING"
  note "Set each by hand with: gh secret set <NAME>"
  SKIPPED+=("GitHub secrets:$MISSING")
fi
pause "Press Enter to continue."

# ── 7. First run ──────────────────────────────────────────────────────────
stage "First run"
say "The daily schedule is 04:30 UTC, but there is no reason to wait a day to"
say "find out whether the credentials work."
note ""
note "This triggers a deliberately small run — three product steps rather than"
note "a whole catalogue — which is enough to prove the archive reaches R2."
printf '\n'
if confirm "Trigger a test run now?"; then
  if gh workflow run archive.yml -f chain=dirk -f max_product_steps=3 >/dev/null 2>&1; then
    printf '  %s✓%s triggered\n' "$GREEN" "$RESET"
    say "Waiting for it to be picked up..."
    sleep 8
    RUN_ID=$(gh run list --workflow archive.yml --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || echo "")
    if [[ -n "$RUN_ID" ]]; then
      say "Watching run $RUN_ID — Ctrl-C stops watching, not the run."
      printf '\n'
      gh run watch "$RUN_ID" --exit-status || warn "the run finished red; see the log above"
    else
      note "Couldn't find the run; check it with: gh run list --workflow archive.yml"
    fi
  else
    warn "couldn't trigger it. The usual cause is that the workflow isn't on the"
    note "  default branch yet. Merge it to main, then: gh workflow run archive.yml"
    SKIPPED+=("trigger the first run: gh workflow run archive.yml -f chain=dirk")
  fi
else
  note "Fine — it will run on its own at 04:30 UTC. To trigger it yourself:"
  note "  gh workflow run archive.yml -f chain=dirk -f max_product_steps=3"
fi

finish
